// Define an Interval struct to represent a valid interval [min, max]
// We use f64 to allow real-valued intervals, suitable for domain and window.
#[derive(Debug, Clone)]
struct Interval {
    min: f64,
    max: f64,
}

impl Interval {
    // Constructor ensures min < max
    fn new(min: f64, max: f64) -> Self {
        assert!(min < max, "Interval min must be less than max");
        Interval { min, max }
    }
}

// Define the main ChebyshevPoly struct
#[derive(Debug, Clone)]
struct ChebyshevPoly {
    coef: Vec<i32>,    // Coefficients converted to i32
    domain: Interval,  // Domain interval [min, max]
    window: Interval,  // Window interval [min, max]
}

// The requested function to construct the Chebyshev polynomial descriptor
fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    // Convert all coefficients from i8 to i32
    let coef_i32: Vec<i32> = coef.into_iter().map(|c| c as i32).collect();

    // Define default domain and window intervals as [-1, 1]
    let domain = Interval::new(-1.0, 1.0);
    let window = Interval::new(-1.0, 1.0);

    // Return the structure
    ChebyshevPoly {
        coef: coef_i32,
        domain,
        window,
    }
}